import{P as K}from"./phaser-DIUF0PZB.js";import{bm as R,ax as S,aA as X,aE as $,aw as y,av as de,aC as j,cS as cs,aD as Y,aB as Ve,az as U,cT as te,cU as ue,t as Ds,ex as Is,bn as Me,ey as Fs,bp as lt,aU as ct,ez as _s,aO as Os,aV as Je,dp as Ws,ah as $s,an as b,dW as Vt,e8 as Xt,aj as ge,ee as Ht,e0 as ke,el as Ut,al as ve,am as Gt,ek as js,eA as Ns,dB as Bs,e6 as Vs,ej as Xs,eh as Hs,ai as zt,bi as ds,eB as Qe,d$ as Kt,bT as us,e2 as Us,b_ as Gs,c0 as rt,c1 as zs,eC as Ks,dJ as Ys,cc as Js,cy as Qs,cB as vt,aT as Zs,bN as eo,eD as to,ay as so}from"./index-CgXJVgpm.js";import{H as Yt,B as J,E as G,an as L,L as Xe,ao as oo,ai as ao,ah as no}from"./scene-kit-CQcOhBcy.js";import{P as He}from"./camp-pixel-kit-ThQFGxLG.js";import{i as hs,h as io,s as ro}from"./village-scout-BGESiTKV.js";import{c as Ze}from"./camp-pixel-sprites-KEmgXAOG.js";import{s as lo,e as co,a as uo,r as ho}from"./paint-loader-Cc-Y4msA.js";import{d as mo,H as fo}from"./arena-C6FlNnmU.js";import{a as po}from"./menu-frame-BjeZc6qq.js";import{e as vo}from"./css-workshop-BkoEamhg.js";import{o as go}from"./npc-dialogue-hQO4ZyvL.js";import{v as et}from"./portraits-BUUIpt_Z.js";import{r as gt,R as yo,f as Jt,e as bo}from"./room-transit-CPBZINMv.js";import"./npc-avatars-DJoJHUzj.js";const wo="Vaucendre",ko="Le village fantôme",To="Parler",Mo="Parler à {{name}}",So="Fermer",xo="Parler encore",Co={label:"Dialogue avec {{name}}",skip:"Passer",skipLabel:"Passer le dialogue",nextLabel:"Toucher pour continuer",erynd:"Erynd"},Po="[[←↑↓→]] marcher · [[{{enter}}]] parler · [[Échap]] carte",qo="Glisse pour marcher, touche pour aller",Ao="La Lanterne Brisée",Lo="La chapelle",Eo="Le poste de garde",Ro="Le guet du rôdeur",Do="La hutte de Mélisse",Io="Le coin des pillards",Fo="Le puits",_o="Vers la carte",Oo="{{n}} or",Wo={cueilleuse:{label:"Linette",name:"Linette",title:"la cueilleuse",greet:"Oh ! Un chevalier… vivant ? Pardon. Ici, on ne croise plus que des ombres et des corbeaux.",lines:["Je cueille encore dans les bois morts. Les champignons, eux, aiment le noir. Ce sont bien les seuls.","Le bois a changé l’hiver où la lanterne de la place s’est fêlée. Les arbres se sont tus d’un coup, comme si on leur avait pris leur nom.","Si tu passes chez Mélisse, dis-lui que l’amanite grise repousse près des souches. Son contre-venin en a besoin.","Ne t’éloigne pas du sentier quand la brume monte. Ce qui pousse là-bas n’a plus de racines."]},soeur:{label:"Sœur Clémence",name:"Sœur Clémence",title:"la sœur de la chapelle",greet:"Entre dans la lumière, voyageur. Elle est petite, mais elle tient encore.",lines:["Cette chandelle est la dernière de la chapelle. Tant qu’elle brûle, les ténèbres s’arrêtent au seuil. Je ne dors plus beaucoup.","Autrefois, on sonnait la cloche pour chaque naissance. Puis pour chaque départ. Puis plus personne n’est venu la sonner.","On dit que, dans la nécropole, une voix appelle les morts par leur nom. Ici, nous prions pour qu’on se souvienne des nôtres.","Si tu portes des noms sur ton bouclier, je peux les dire avec toi, ce soir. Personne ne devrait être oublié deux fois."]},melisse:{label:"Mélisse",name:"Mélisse",title:"la sorcière des simples",greet:"Doucement, chevalier, tu marches sur ma sauge. Je ne mords pas : je fais des tisanes, des fioles et, parfois, de modestes miracles.",lines:["Les gens du village avaient peur de moi. Maintenant qu’ils sont partis, c’est moi qui ai peur pour eux.","Les ténèbres d’ici ne sont pas une malédiction de sorcière. Je le saurais. C’est plus ancien : ça ronge les noms avant les pierres.","Linette me rapporte ce qui pousse encore dans le noir. Avec ça, je tiens le venin et la braise à distance. Un peu.","Une fiole ne gagne pas un combat. Elle te laisse le temps de le gagner toi-même."],service:"Potions",intro:"Une fiole de chaque, pas plus : elles tournent si on les garde trop longtemps. Elles partent avec toi à ta prochaine expédition.",bought:"Voilà. Bois-la quand il faudra - ou laisse-la faire, celle-là sait quand.",short:"Il te manque {{n}} pièces, chevalier. Je fais crédit aux morts, pas aux vivants."},ancien:{label:"Anselme",name:"Anselme",title:"le doyen de Vaucendre",greet:"Approche, que je voie ton visage. Mes yeux ne gardent plus les visages, mais j’essaie.",lines:["Vaucendre avait des vergers jusqu’au plateau. À la fête des lanternes, on en accrochait une à chaque porte, et les montagnes nous répondaient en violet.","Puis les lanternes se sont fêlées une à une. Les gens partaient au matin et, le soir, plus personne ne se rappelait leur nom.","Ce puits donnait l’eau la plus claire de la contrée. Il est sec depuis que la cloche de la chapelle s’est tue. Je ne crois pas au hasard.","Moi, je reste. Quelqu’un doit se souvenir du village tel qu’il était. Sinon, il disparaît pour de bon.","Si tu repars, chevalier, emporte au moins son nom : Vaucendre. Dis-le à voix haute, une fois, là-bas."]},odo:{label:"Odo",name:"Odo Grisfer",title:"sergent de la Compagnie des Cendres",greet:"Un chevalier en armure, à Vaucendre ? Assieds-toi. La taverne est morte, mais le banc tient.",lines:["La Compagnie des Cendres ? Pas un régiment : ce qui reste des régiments. Ceux que la guerre contre Krynax a laissés sans route, sans solde et sans nom à graver.","J’ai servi sous des étendards qu’on laisse pourrir aujourd’hui sur la colline. Je ne demande plus qui a gagné. Je demande qui est rentré.","La taverne s’appelait la Lanterne Brisée bien avant que la lanterne se brise. Le patron disait que ça portait chance. Il avait de l’humour.","Ton bouclier… cent treize noms, hein ? On a tous nos listes. Moi, je récite la mienne au comptoir, le soir. Il ne répond plus, mais il écoute bien.","Quand tu seras au bout de ta route, reviens. La Compagnie garde toujours une place à table pour ceux qui reviennent."]},brann:{label:"Brann",name:"Brann Pique-Cendre",title:"sapeur de la Compagnie",greet:"Hé ! Mets pas ta botte sur ma pioche. Elle a creusé sous trois sièges et ouvert un tonneau, elle mérite le respect.",lines:["J’étais sapeur. On creusait sous les murs ennemis pendant que les chevaliers paradaient devant. Les murs tombaient, les chevaliers prenaient les médailles.","Sous les montagnes, les galeries chantent, depuis peu. Pas le bon chant. J’ai remonté ma lampe et je suis venu boire ici.","Les ténèbres autour du village ? Ça vient d’en bas, je te le dis. Ça remonte par les racines, par les puits. Ça a soif de quelque chose.","Ma lampe de casque n’a jamais tremblé dans une mine. Ici, elle tremble toutes les nuits. Je dis ça, je dis rien.","Si un jour tu as besoin qu’un mur tombe, tu sais où me trouver. Apporte à boire."]},capitaine:{label:"Gaspard",name:"Gaspard Ombrecourt",title:"ancien capitaine de la garde",greet:"N’approche pas trop. Ces chaînes, c’est moi qui les ai bouclées. Un capitaine qui a perdu sa ville ne mérite pas de marcher librement.",lines:["La garde de Vaucendre comptait vingt hommes. De bons hommes. Des fils de paysans à qui j’avais appris à tenir une lance.","La nuit où les ténèbres sont descendues des bois, j’ai ordonné de tenir la place. Nous l’avons tenue jusqu’à l’aube. Il en restait trois.","Au matin, les survivants ne se souvenaient plus du nom des tombés. Moi, si. C’est pour ça que je reste : je suis la seule liste qui tienne encore debout.","Tu veux m’aider ? Montre-moi que la garde peut encore se lever. Passe mes épreuves. Chaque fois que tu en réussis une, je me souviens d’un homme sans avoir honte."],service:"Épreuves",story:"La chute de la garde",intro:"Une arène que tu connais déjà, une règle, pas d’excuse. Elle coûte l’énergie de l’arène, comme toujours. La première victoire est récompensée ; les suivantes, c’est pour l’honneur.",outcome:{won:"Bien. Très bien. Prends ceci, tu l’as gagné.",wonPotion:"Et cette fiole : Mélisse me la gardait pour une nuit pire que les autres.",again:"Encore. Ça ne s’use pas, ce genre de choses.",hit:"Touché. Sur le rempart, ça aurait suffi. Recommence quand tu veux.",time:"Trop lent. La nuit n’attend pas que la garde ait fini sa ronde.",power:"J’ai dit la lame seule. Le reste, c’est de la magie, pas de la discipline.",fell:"Relève-toi. Moi, je ne l’ai pas fait à temps. Toi, tu peux.",abandon:"On ne quitte pas son poste. Sauf pour revenir le tenir mieux."}},zahir:{label:"Zahir",name:"Zahir Sourire-d’Or",title:"chef des pillards",greet:"Tiens, tiens. Une armure qui brille encore, dans un village pareil ? Avance doucement, chevalier : mes garçons ont la main nerveuse et la mémoire courte.",lines:["Pillards ? Quel vilain mot. Nous sommes des collecteurs. Le village ne se sert plus de ses chandeliers : nous leur trouvons une seconde vie.","Tu cherches qui a tracé ce trait noir sur les cartes ? Moi aussi, figure-toi. Quelqu’un paie cher pour qu’on garde les routes vides. Pas assez cher pour moi.","Gorvak était un client. Mauvais payeur, très mauvais caractère. Je ne le pleure pas, mais je n’oublie pas qui a fermé son fort. Merci, au fait.","La sœur prie, le capitaine se punit, le vieux se souvient. Moi, je compte. Et je compte bien que tu repartes avant la nuit.","Un conseil gratuit - c’est rare, savoure-le : ne fais jamais confiance à une lanterne qui brûle sans huile."],barks:["Passe ton chemin, la boîte de conserve.","Le chef a dit pas touche. Pour l’instant.","Jolies bottes. Ce serait dommage de les perdre."]},rodeur:{label:"Corentin",name:"Corentin",title:"le rôdeur cartographe",greet:"Ne bouge pas ! … Voilà, je t’ai noté sur la carte : « chevalier, une armure, l’air fatigué ». Ça te va ?",lines:["Je cartographie ce que les ténèbres effacent. Chaque matin, un chemin manque. Alors je le redessine de mémoire, avant qu’elle aussi s’en aille.","Le trait noir sur les vieilles cartes ? Je l’ai vu aussi. Il relie des lieux que personne ne relierait. Comme si quelqu’un traçait une route à l’envers.","Ma longue-vue voit loin, ma boussole voit juste. Elles se disputent souvent, mais elles ont rarement tort.","Donne-moi quelques pièces et je pars devant. Je te dirai ce qui t’attend, ou par où passent les chemins que les murs cachent."],service:"Éclaireur",scout:"Éclairer la route",scoutText:"Ce qui t’attend dans l’arène {{n}} - {{name}}, ton prochain départ. Noté sur ta carte, pour de bon.",scoutDone:"Déjà noté sur ta carte.",rumour:"Chemins oubliés",rumourText:"Une salle secrète que tu n’as pas encore trouvée : son arène et son mur, notés sur ta carte.",rumourNone:"Tu as trouvé tous les passages que je connais. Respect.",reportTitle:"Arène {{n}} · {{name}}",rumourTitle:"Une salle secrète",rumourSaid:"Arène {{n}} - {{name}} : un passage dans le mur de {{side}}. Frappe ce qui sonne creux.",short:"Il te manque {{n}} pièces. Les cartes ne se dessinent pas toutes seules."}},$o={seve:{name:"Fiole de sève-rouge",desc:"La première fois que tes PV passent sous {{below}} %, tu la bois d’un trait : +{{heal}} % de tes PV max. Une seule fois."},cinder:{name:"Élixir de cendre-froide",desc:"Dégâts de feu −{{n}} % pendant toute l’expédition."},antidote:{name:"Contre-venin",desc:"Dégâts sur la durée −{{dot}} % ; les toiles et la vase te ralentissent bien moins (−{{slow}} %)."},oil:{name:"Huile de lame noire",desc:"Dégâts +{{n}} % pendant toute l’expédition."},carried:"Dans ta besace",buy:"Acheter",satchel:"Ta besace : {{list}}",satchelEmpty:"Ta besace est vide.",rule:"Tes fioles partent avec ta prochaine expédition depuis le camp, puis elles sont bues."},jo={ronde:{name:"La ronde du guet",desc:"Nettoie l’arène {{n}} - {{arena}} - en moins de {{s}} secondes."},egratignure:{name:"Pas une égratignure",desc:"Nettoie l’arène {{n}} - {{arena}} - sans être touché une seule fois."},lame:{name:"La lame seule",desc:"Nettoie l’arène {{n}} - {{arena}} - sans lancer ton pouvoir."},ligne:{name:"Tenir la ligne",desc:"Tiens l’arène {{n}} - {{arena}} - en mode Héroïque."},serment:{name:"Le serment de la garde",desc:"L’arène {{n}} - {{arena}} - en mode Héroïque, en moins de {{s}} secondes."},go:"Relever l’épreuve",again:"Rejouer",reward:"Récompense : {{gold}} or",rewardPotion:"Récompense : {{gold}} or et une {{potion}}",won:"Réussie",locked:"Franchis l’arène {{n}}",lockedAfter:"Après les quatre autres épreuves",energy:"Il te manque de l’énergie · +1 dans {{time}}",cost:"{{n}} ⚡"},No={enemies:"Ennemis : {{list}}",elites:"Élites : {{list}}",guardian:"Un gardien : le champion de la contrée",invaders:"Envahisseurs : {{list}}",boss:"Boss : {{name}}",water:"Des mares au sol : elles ralentissent.",left:"gauche",right:"droite"},Bo={title:"Épreuve : {{name}}",won:"Réussie",failed:"Manquée"},Vo="Un corbeau",Xo={title:wo,subtitle:ko,talk:To,talkTo:Mo,close:So,more:xo,dialogue:Co,keys:Po,joystick:qo,tavern:Ao,chapel:Lo,guardPost:Eo,lookout:Ro,hut:Do,camp:Io,well:Fo,exitSign:_o,gold:Oo,npc:Wo,potion:$o,trial:jo,scout:No,trialBack:Bo,crow:Vo},ie=2,Ho=1672,Uo=941,ye=Ho*ie,Pe=Uo*ie,E=ie,tt=300,Mt=120,Qt=190,Go=40,Oe={from:{x:80,y:1470},to:{x:300,y:1470}},zo={x:1280,y:1530},Ko={x:14,y:Oe.from.y-70},oe=[{id:"soeur",role:"talk",x:355*E,y:308*E,face:1,lines:4},{id:"melisse",role:"potions",x:338*E,y:670*E,face:1,lines:4},{id:"cueilleuse",role:"talk",x:650*E,y:426*E,face:1,lines:4},{id:"capitaine",role:"trials",x:652*E,y:692*E,face:-1,lines:4},{id:"ancien",role:"talk",x:905*E,y:462*E,face:1,lines:5},{id:"brann",role:"talk",x:1212*E,y:294*E,face:1,lines:5},{id:"odo",role:"talk",x:1300*E,y:392*E,face:1,lines:5},{id:"zahir",role:"talk",x:1412*E,y:620*E,face:1,lines:5},{id:"rodeur",role:"scout",x:1592*E,y:646*E,face:-1,lines:4}],St=[{x:1348*E,y:646*E,face:1,barks:3},{x:1520*E,y:702*E,face:-1,barks:3}],ms=[{id:"seve",price:120},{id:"cinder",price:90},{id:"antidote",price:80},{id:"oil",price:110}],fs=[{id:"ronde",arena:8,rule:"timed",limitMs:45e3,heroic:0,gold:150},{id:"egratignure",arena:3,rule:"noHit",heroic:0,gold:200},{id:"lame",arena:17,rule:"noPower",heroic:0,gold:250},{id:"ligne",arena:24,rule:"clear",heroic:1,gold:300},{id:"serment",arena:34,rule:"timed",limitMs:7e4,heroic:1,gold:400,potion:"seve",after:["ronde","egratignure","lame","ligne"]}],Yo=15,je=120,q